SELECT 'OUTCOME' AS src, interval_code, candle_open_time, outcome AS state, reason_code AS reason, origin AS kind, COUNT(*) AS n, MIN(created_at) AS first_raw, MAX(created_at) AS last_raw FROM candle_analysis_outcome WHERE candle_open_time BETWEEN '2026-10-10 17:00:00' AND '2026-10-10 18:00:00' AND (interval_code='1h' OR candle_open_time >= '2026-10-10 17:54:00') GROUP BY interval_code, candle_open_time, outcome, reason_code, origin UNION ALL SELECT 'RECON', interval_code, candle_open_time, status, failure_reason, subject_type, COUNT(*), MIN(created_at), MAX(resolved_at) FROM local_reconciliation_audit WHERE created_at BETWEEN '2026-10-10 17:50:00' AND '2026-10-10 18:40:00' GROUP BY interval_code, candle_open_time, status, failure_reason, subject_type ORDER BY 1,2,3